style.css:
@-moz-document domain("youtube.com") {
/* General Background */
    body, #page-manager, ytd-app {
        background-color: #0f0f0f !important;
        color: #b0b0b0 !important;
    }

    /* Header */
    #masthead-container, ytd-masthead {
        background-color: #1a1a1a !important;
        border-bottom: 2px solid #008f11 !important;
        box-shadow: 0 4px 8px rgba(0, 143, 17, 0.2);
    }

    /* Search Bar */
    #search-form {
        background-color: #222 !important;
        border: 1px solid #00ff99 !important;
        border-radius: 8px !important;
    }

    #search-icon-legacy, #guide-icon, #logo-icon-container {
        color: #00ff99 !important;
    }

    /* Video Titles */
    #video-title, h1.title.style-scope.ytd-video-primary-info-renderer {
        color: #ffffff !important;
        font-weight: bold !important;
    }

    /* Sidebar Menu */
    #guide-content, ytd-guide-section-renderer, ytd-guide-entry-renderer {
        background-color: #141414 !important;
        color: #00ff99 !important;
        border-left: 2px solid #008f11 !important;
    }

    #guide-icon, ytd-mini-guide-entry-renderer a {
        color: #00ff99 !important;
    }

    /* Video Thumbnails */
    ytd-thumbnail {
        border: 1px solid #008f11 !important;
        transition: transform 0.2s ease-in-out;
    }

    ytd-thumbnail:hover {
        border-color: #00ff99 !important;
        transform: scale(1.05);
    }

    /* Buttons and Icons */
    #top-level-buttons-computed ytd-toggle-button-renderer {
        color: #00cc88 !important;
    }

    #top-level-buttons-computed ytd-toggle-button-renderer:hover {
        color: #00ff99 !important;
    }

    /* Subscribe Button */
    #subscribe-button, ytd-subscribe-button-renderer {
        background-color: #00cc88 !important;
        color: #ffffff !important;
        border-radius: 4px;
        padding: 5px 10px;
    }

    #subscribe-button:hover {
        background-color: #00ff99 !important;
    }

    /* Comments Section */
    #comments, ytd-comment-thread-renderer {
        background-color: #1a1a1a !important;
        border-top: 1px solid #008f11 !important;
        color: #b0b0b0 !important;
    }

    ytd-comment-renderer #content-text {
        color: #cccccc !important;
    }

    ytd-comment-renderer #author-text {
        color: #00ff99 !important;
    }

    /* Footer */
    #footer {
        background-color: #1a1a1a !important;
        color: #008f11 !important;
    }
}
